    flex: 1,
  },
  resultCount: {
    color: Colors.textMuted,
    fontSize: 12,
    paddingHorizontal: 20,
    paddingTop: 10,
    paddingBottom: 6,
  },
  list: {
    paddingHorizontal: 16,
    paddingBottom: 20,
  },
});

