    marginBottom: 20,
  },
  title: {
    fontSize: 30,
    fontWeight: '900' as const,
    color: Colors.text,
    letterSpacing: -0.8,
    marginBottom: 4,
  },
  subtitle: {
    fontSize: 13,
    color: Colors.textSecondary,
  },
  shareStatsButton: {
    width: 44,
    height: 44,
    borderRadius: 14,
    backgroundColor: Colors.accent,
    justifyContent: 'center',
    alignItems: 'center',
  },
  completionCard: {
    borderRadius: 20,
    padding: 20,
    marginBottom: 16,
    borderWidth: 1,
    borderColor: Colors.accent + '20',
    overflow: 'hidden',
  },
  completionTop: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 16,
  },
  completionLabel: {
    fontSize: 10,
    color: Colors.accent,
    fontWeight: '700' as const,
    letterSpacing: 1.2,
    marginBottom: 4,
  },
